css:
/* ==========================================================================
   SANGUINE KEEP  -  a gothic castle theme for Marinara Engine
   Structural idea: "Lancet & Reliquary". Every surface is a piece of the keep:
   - messages are chamfered reliquary panels (cut corners, double gilt rule,
     quatrefoil studs) and the speaker's name is struck on a pointed banner plaque;
   - every portrait is a pointed lancet window, the send button is a lancet;
   - the top bar is a battlement: crenellated lower edge, arched doorway tabs;
   - the sidebar is the tower wall: stone courses, mortar joints, a lit niche
     for the open chat; the Chats | Library switch is a pair of arched doors;
   - Home widgets, dialogs and pages are reliquary panels with banner eyebrows.
   ========================================================================== */

:root {
  --mari-tokens-version: 1;
  --radius: 0px;

  --mari-font-ui: "Crimson Pro", "EB Garamond", Georgia, serif;
  --mari-font-heading: "Cinzel", "Crimson Pro", Georgia, serif;
  --mari-font-chat: "Crimson Pro", "EB Garamond", Georgia, serif;
  --mari-chat-font-size: 18px;
  --mari-chat-line-height: 1.55;
  --mari-paragraph-gap: 0.7em;
  --mari-dialogue-weight: 500;
  --mari-text-outline: 0;
  --mari-min-ui-text: 14px;
  --text-xs: 0.875rem;
  --text-sm: 0.9375rem;
  --mari-toast-font-size: 15px;

  --mari-selected-tint: var(--primary);
  --mari-top-bar-plate-radius: 0;
  --mari-home-widget-radius: 0;
  --mari-home-widget-border: transparent;
  --mari-home-widget-border-width: 0px;
  --mari-home-widget-title-font: "Cinzel", Georgia, serif;
  --mari-home-widget-title-size: 1.3rem;
  --mari-home-widget-text-size: 15px;
  --mari-home-widget-eyebrow-size: 11px;
  --mari-home-art: none;
  --mari-chat-row-art-opacity: 0;
  --mari-phone-avatar: hidden;
  --mari-vn-fade: 1.5rem;

  --mari-app-backdrop-size: cover;
  --mari-app-backdrop-position: center;

  /* weather: this keep is old stone and candlelight */
  --mari-weather-style: smooth;
  --mari-weather-lightning-bolt: 0.7;
  --mari-weather-rain-length: 1.6;
  --mari-weather-speed: 0.9;
  --mari-weather-petal-image: url("theme:wx-petal-1.png") url("theme:wx-petal-2.png") url("theme:wx-petal-3.png");
  --mari-weather-petal-size: 1.6;
  --mari-weather-leaf-image: url("theme:wx-leaf-1.png") url("theme:wx-leaf-2.png") url("theme:wx-leaf-3.png");
  --mari-weather-leaf-size: 0.85;
  --mari-weather-ember-color: #ffb45c;
  --mari-weather-ember-shape: round;
  --mari-weather-snow-shape: round;
  --mari-weather-moon: none;

  --ck-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* ---------------------------------------------------------------- night -- */
:root[data-theme="dark"] {
  --background: #0c0709;
  --foreground: #efe5d6;
  --card: rgba(18, 9, 12, 0.88);
  --card-foreground: #efe5d6;
  --popover: #150a0e;
  --popover-foreground: #efe5d6;
  --primary: #b82a3a;
  --primary-foreground: #fbefe2;
  --secondary: #24121a;
  --secondary-foreground: #efe5d6;
  --muted: #1d1015;
  --muted-foreground: #bfae9c;
  --accent: #2c1219;
  --accent-foreground: #f3dca0;
  --destructive: #d4463c;
  --destructive-foreground: #fff4ea;
  --border: rgba(201, 162, 74, 0.3);
  --input: rgba(201, 162, 74, 0.34);
  --ring: #c9a24a;
  --sidebar: #0d080a;
  --sidebar-foreground: #efe5d6;
  --sidebar-border: rgba(201, 162, 74, 0.28);
  --sidebar-accent: #2a0f17;
  --sidebar-accent-foreground: #f6e7c4;

  --ov-line: rgba(201, 162, 74, 0.24);
  --ck-row-solid: #150b0f;
  --ov-text: #efe5d6;
  --ov-muted: #c0ae9b;
  --ov-dim: #8f7f72;
  --ov-accent: #b82a3a;
  --ov-hover: rgba(201, 162, 74, 0.1);
  --ov-active-bg: rgba(163, 24, 44, 0.32);
  --mari-chrome-accent: #b3263a;
  --mari-chrome-muted: #bba994;
  --mari-accent-text: #e0bc63;

  --ck-gilt: #c9a24a;
  --ck-gilt-hi: #e8c879;
  --ck-crimson: #8f1d2c;
  --ck-crimson-deep: #5c0f1a;
  --ck-plaque-text: #fbecd2;
  --ck-ink: #efe5d6;
