  --mari-chat-header-bg: linear-gradient(180deg, rgba(12, 6, 9, 0.92), rgba(12, 6, 9, 0));
  --mari-page-floor: rgba(13, 7, 10, 0.93);
  --mari-stage-empty-bg: radial-gradient(ellipse at 30% 20%, #2a0f17 0%, #0c0709 70%);
  --mari-user-avatar-placeholder: linear-gradient(160deg, #5c0f1a, #1a0b10);
  --mari-card-art-placeholder: radial-gradient(ellipse at 50% 0%, rgba(201, 162, 74, 0.25), transparent 60%), linear-gradient(180deg, #2a0f17, #0f080b);
  --mari-top-bar-plate: rgba(16, 8, 11, 0.82);
  --mari-top-bar-plate-active: rgba(110, 20, 34, 0.9);
  --mari-pinned-speaker-bg: rgba(18, 9, 12, 0.96);


  --ck-frame: url("theme:frame-n.svg");
  --ck-frame-latest: url("theme:frame-latest-n.svg");
  --ck-frame-panel: url("theme:frame-panel-n.svg");
  --ck-iron: url("theme:iron-n.svg");
  --ck-lancet-frame: url("theme:lancet-frame-n.svg");
  --ck-send: url("theme:send-n.svg");
  --ck-divider: url("theme:divider-n.svg");

  --mari-weather-rain-color: #a9b9d6;
  --mari-weather-snow-color: #e6ecf7;
  --mari-weather-fog-color: #6d7488;
  --mari-weather-lightning-color: #eef1ff;
  --mari-weather-star-color: #e9e3ff;
  --mari-weather-firefly-color: #ffcf7a;
  --mari-weather-ash-color: #8a8088;
  --mari-weather-dust-color: #c9a24a;
  --mari-weather-tint-strength: 0.3;
  --mari-weather-strength: 1.05;
}

/* ------------------------------------------------------------------ day -- */
