  --ck-gilt-hi: #6e5212;
  --ck-crimson: #8f1d2c;
  --ck-crimson-deep: #6a1220;
  --ck-plaque-text: #fff3e0;
  --ck-ink: #2a1912;
  --ck-shadow: 0 6px 16px -10px rgba(60, 30, 10, 0.45);
  --ck-stone: #e9dfcc;
  --ck-leaf: rgba(250, 245, 235, 0.86);
  --ck-leaf-solid: #faf5eb;
  --ck-field: rgba(251, 247, 239, 0.92);
  --ck-slot: #ddd0b8;
  --ck-knob-off: #fbf6ec;
  --ck-course: rgba(250, 244, 233, 0.92);
  --ck-pane-top: rgba(250, 244, 233, 0.96);
  --ck-pane-bottom: rgba(240, 231, 214, 0.96);
  --ck-ember: #8f1d2c;
  --mari-home-wash: rgba(246, 240, 229, 0.72);

  --mari-mode-conversation: #2f5a96;
  --mari-mode-roleplay: #8f1d2c;
  --mari-mode-game: #7a5a16;
  --ov-mode-conversation: #2f5a96;
  --ov-mode-roleplay: #8f1d2c;
  --ov-mode-game: #7a5a16;
  --mari-home-pink: #8f1d2c;
  --mari-home-violet: #5b3f8a;
  --mari-gauge-ok: #3d7a46;
  --mari-gauge-warn: #9a6a12;
  --mari-gauge-danger: #a32020;
  --mari-dialogue-color: #7a1424;
  --mari-resource-accent: #8f1d2c;
  --mari-resource-characters: #8f1d2c;
  --mari-resource-personas: #7a2a6a;
  --mari-resource-lorebooks: #2f5a96;
  --mari-resource-presets: #7a5a16;
  --mari-resource-connections: #2f6b4a;
  --mari-resource-agents: #7a2a6a;
  --mari-resource-settings: #5a4a42;
  --mari-resource-backgrounds: #2f5a96;
  --mari-resource-browser: #2f6b4a;
  --mari-ctrlk-conversation: #2f5a96;
  --mari-ctrlk-roleplay: #8f1d2c;
  --mari-ctrlk-game: #7a5a16;
  --mari-message-time: #6e5a4a;
  --mari-message-actions: #6a5546;
  --mari-swipe-counter: #6a5546;
  --mari-home-widget-title-color: #2a1912;
  --mari-home-widget-muted: #5c493b;
  --mari-home-widget-eyebrow-color: #fff3e0;
  --mari-scrim: rgba(40, 22, 14, 0.45);
