  --mari-card-art-placeholder: radial-gradient(ellipse at 50% 0%, rgba(143, 29, 44, 0.18), transparent 60%), linear-gradient(180deg, #efe2c9, #d7c4a3);
  --mari-top-bar-plate: rgba(251, 246, 236, 0.85);
