}

:root[data-mari-weather="fog"] {
  --mari-weather-tint-strength: 0.8;
}

/* ============================================================ type ====== */
[data-mari-part="page-title"],
.mari-home-hero h1 {
  font-family: "Pirata One", "Cinzel", Georgia, serif !important;
  font-weight: 400 !important;
  letter-spacing: 0.01em !important;
}
.mari-home-hero h1 {
  font-size: clamp(1.7rem, 2.4vw, 2.5rem) !important;
  color: var(--ck-ink) !important;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.35);
}
[data-mari-part="page-title"] {
  font-size: 2.1rem !important;
  color: var(--ck-ink);
}

/* the stock chat background steps aside for the castle */
img[data-mari-part="backdrop"][data-default-background] {
  opacity: 0 !important;
}
/* ================================================ the hall and its windows ==
   One backdrop per scheme and weather; each has its own window stencil (--ck-win), white where the
   glass is. Landscape screens see the great hall, portrait screens (phones, iPad portrait) the stair
   tower. --ck-ar is the picture's aspect ratio, --ck-top 1 when the art is pinned to the top. */
:root {
  --ck-ar: 1.7768;
  --ck-top: 0;
}
:root[data-theme="dark"] { --mari-app-backdrop: url("theme:night-hall.webp"); --ck-win: url("theme:win-night-hall.png"); }
:root[data-theme="dark"]:is([data-mari-weather="storm"], [data-mari-weather="rain"]) { --mari-app-backdrop: url("theme:storm-hall.webp"); --ck-win: url("theme:win-storm-hall.png"); }
:root[data-theme="dark"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --mari-app-backdrop: url("theme:snow-hall.webp"); --ck-win: url("theme:win-snow-hall.png"); }
:root[data-theme="dark"][data-mari-weather="fog"] { --mari-app-backdrop: url("theme:fog-hall.webp"); --ck-win: url("theme:win-fog-hall.png"); }
:root[data-theme="light"] { --mari-app-backdrop: url("theme:day-hall.webp"); --ck-win: url("theme:win-day-hall.png"); }
:root[data-theme="light"]:is([data-mari-weather="storm"], [data-mari-weather="rain"]) { --mari-app-backdrop: url("theme:storm-day.webp"); --ck-win: url("theme:win-storm-day.png"); }
:root[data-theme="light"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --mari-app-backdrop: url("theme:snow-day.webp"); --ck-win: url("theme:win-snow-day.png"); }
:root[data-theme="light"][data-mari-weather="fog"] { --mari-app-backdrop: url("theme:fog-day.webp"); --ck-win: url("theme:win-fog-day.png"); }
@media (orientation: portrait) {
  :root {
    --ck-ar: 0.5;
    --ck-top: 1;
    --mari-app-backdrop-position: center top;
  }
  :root[data-theme="dark"] { --mari-app-backdrop: url("theme:phone-night.webp"); --ck-win: url("theme:win-phone-night.png"); }
  :root[data-theme="dark"]:is([data-mari-weather="storm"], [data-mari-weather="rain"]) { --mari-app-backdrop: url("theme:phone-storm.webp"); --ck-win: url("theme:win-phone-storm.png"); }
  :root[data-theme="dark"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --mari-app-backdrop: url("theme:phone-snow.webp"); --ck-win: url("theme:win-phone-snow.png"); }
  :root[data-theme="dark"][data-mari-weather="fog"] { --mari-app-backdrop: url("theme:phone-fog.webp"); --ck-win: url("theme:win-phone-fog.png"); }
  :root[data-theme="light"] { --mari-app-backdrop: url("theme:phone-day.webp"); --ck-win: url("theme:win-phone-day.png"); }
  :root[data-theme="light"]:is([data-mari-weather="storm"], [data-mari-weather="rain"]) { --mari-app-backdrop: url("theme:phone-storm-day.webp"); --ck-win: url("theme:win-phone-storm-day.png"); }
  :root[data-theme="light"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --mari-app-backdrop: url("theme:phone-snow-day.webp"); --ck-win: url("theme:win-phone-snow-day.png"); }
  :root[data-theme="light"][data-mari-weather="fog"] { --mari-app-backdrop: url("theme:phone-fog-day.webp"); --ck-win: url("theme:win-phone-fog-day.png"); }
}

/* The window check. The hall is indoors: moving weather (rain, snow, petals, leaves, the bolt and the
   storm wash) shows only through the window glass of the picture behind it. The weather canvas covers
   the chat pane (from the left edge, under the top bar) while the backdrop covers the whole window, so
   the stencil is sized like the backdrop (cover) and shifted up by the top bar's height.
   Only while the theme's hall is what shows: a chat with its own background has no
   data-default-background image, and the app's own scene stencils keep working untouched. */
/* the stencil applies only while the chat shows the theme's hall: the canvas must sit beside the app's backdrop
   <img>s (the game stage's canvas has none: it paints its own scene), the chat must not be a game, and no
   backdrop <img> may carry a picture of its own (by night the app's default plate is marked
   data-default-background, by day no backdrop has a src at all). The app's own scene stencil is an inline
   style and wins over this rule. */
:root:not([data-chat-open-mode="game"]) :has(> img[data-mari-part="backdrop"]):has(> canvas[data-mari-part="weather"]):not(:has(> img[data-mari-part="backdrop"][src]:not([data-default-background]))) > canvas[data-mari-part="weather"] {
  --ck-bw: max(100vw, 100vh * var(--ck-ar));
  --ck-bh: max(100vh, 100vw / var(--ck-ar));
  -webkit-mask-image: var(--ck-win);
  mask-image: var(--ck-win);
  -webkit-mask-size: var(--ck-bw) var(--ck-bh);
  mask-size: var(--ck-bw) var(--ck-bh);
  -webkit-mask-position: calc((100vw - var(--ck-bw)) / 2) calc((100vh - var(--ck-bh)) / 2 * (1 - var(--ck-top)) - var(--mari-top-bar-height, 45px));
  mask-position: calc((100vw - var(--ck-bw)) / 2) calc((100vh - var(--ck-bh)) / 2 * (1 - var(--ck-top)) - var(--mari-top-bar-height, 45px));
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
}

/* ============================ the battlement: a blind arcade frieze ==== */
:root[data-theme="dark"] {
  --mari-top-bar-bg: url("theme:frieze-night.webp") left center / auto 100% repeat-x, #140b10;
}
:root[data-theme="light"] {
  --mari-top-bar-bg: url("theme:frieze-day.webp") left center / auto 100% repeat-x, #efe6d6;
}
[data-mari-part="top-bar"] {
  border-bottom: 1px solid var(--ck-gilt) !important;
  box-shadow: 0 3px 10px -6px rgba(0, 0, 0, 0.6);
  font-family: var(--mari-font-ui);
}
[data-mari-part="top-bar"] .ov-tab,
[data-mari-part="top-bar"] .ov-text-btn {
  border-radius: 14px 14px 0 0 / 10px 10px 0 0 !important;
  border: 1px solid transparent;
  border-bottom: 0;
  font-size: 15px;
}
[data-mari-part="top-bar"] .ov-tab.is-on,
[data-mari-part="top-bar"] .ov-text-btn.is-on {
  border-color: var(--ck-gilt);
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep)) !important;
  color: var(--ck-plaque-text) !important;
}
[data-mari-part="top-bar"] .ov-tab.is-on .ov-tab__label,
[data-mari-part="top-bar"] .ov-tab.is-on svg,
[data-mari-part="top-bar"] .ov-text-btn.is-on svg,
[data-mari-part="top-bar"] .ov-text-btn.is-on span {
  color: var(--ck-plaque-text) !important;
}
[data-mari-part="top-bar"] .ov-tab__label,
[data-mari-part="top-bar"] .ov-text-btn > span {
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.04em;
}
[data-mari-part="top-bar"] .ov-text-btn small {
  font-family: var(--mari-font-ui);
  font-size: 14px;
}

/* ======================================================= the tower ====== */
[data-component="RightPanelDesktop"],
[data-component="RightPanelDesktopSlot"] {
  border-left: 1px solid var(--ck-gilt) !important;
}
:root[data-theme="dark"] .ov-sidepane {
  background:
    url("theme:stone-tile.webp") 0 0 / 300px auto repeat,
    linear-gradient(90deg, rgba(10, 5, 7, 0.84), rgba(12, 6, 9, 0.8));
}
:root[data-theme="light"] .ov-sidepane {
  background:
    url("theme:stone-day.webp") 0 0 / 300px auto repeat,
    linear-gradient(90deg, rgba(242, 235, 221, 0.86), rgba(238, 229, 211, 0.82));
}
/* the pair of arched doors */
.ov-sideswitch {
  border-radius: 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-bottom: 1px solid var(--ck-gilt) !important;
  padding-bottom: 0 !important;
  gap: 6px !important;
}
.ov-sideswitch__btn {
  border-radius: 50% 50% 0 0 / 16px 16px 0 0 !important;
  border: 1px solid var(--ov-line) !important;
  border-bottom: 0 !important;
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
  letter-spacing: 0.05em;
  box-shadow: none !important;
}
.ov-sideswitch__btn.is-on {
  border-color: var(--ck-gilt) !important;
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep)) !important;
  color: var(--ck-plaque-text) !important;
}
.ov-sideswitch__btn.is-on svg,
.ov-sideswitch__btn.is-on span {
  color: var(--ck-plaque-text) !important;
}
.mari-sidebar-header h2 {
  font-family: "Cinzel", Georgia, serif;
  letter-spacing: 0.06em;
  font-size: 15px !important;
}
/* stone courses */
[data-chat-row] {
  border-radius: 0 !important;
  border-bottom: 1px solid var(--ov-line);
  margin-bottom: 0 !important;
}
[data-chat-row][data-selected="true"] {
  background: linear-gradient(90deg, rgba(163, 24, 44, 0.55), rgba(163, 24, 44, 0.08) 85%) var(--ck-row-solid) !important;
  box-shadow: inset 3px 0 0 var(--ck-gilt) !important;
  border-color: var(--ck-gilt) !important;
}
:root[data-theme="light"] [data-chat-row][data-selected="true"] {
  background: linear-gradient(90deg, rgba(143, 29, 44, 0.16), rgba(143, 29, 44, 0.02) 85%) var(--ck-row-solid) !important;
}
@media (hover: hover) {
  [data-chat-row]:hover {
    background: linear-gradient(var(--ov-hover), var(--ov-hover)) var(--ck-row-solid);
  }
}
.ov-new-pill {
  border-radius: 12px 12px 0 0 / 9px 9px 0 0 !important;
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep)) !important;
  border: 1px solid var(--ck-gilt) !important;
  color: var(--ck-plaque-text) !important;
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
  box-shadow: none !important;
}
.mari-chrome-segmented {
  border-radius: 0 !important;
}
.mari-chrome-segmented__button {
  border-radius: 0 !important;
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600 !important;
}
.mari-chrome-segmented__button--selected {
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep)) !important;
  color: var(--ck-plaque-text) !important;
  box-shadow: inset 0 0 0 1px var(--ck-gilt) !important;
}
.mari-chrome-segmented__button--selected * {
  color: var(--ck-plaque-text) !important;
}

/* every small control: square stone, never pills */
.mari-chrome-control,
.ov-icon-btn,
.ov-text-btn,
.ov-rpf__btn,
input,
select,
textarea {
  border-radius: 0 !important;
}

/* ======================================================== portraits ===== */
/* every portrait is a lancet window: gilt pointed-arch frame, picture masked inside */
.mari-message-avatar > div {
  display: flex;
  line-height: 0;
  background: var(--ck-lancet-frame) center / 100% 100% no-repeat;
  padding: 3px 3px 2px;
  border-radius: 0;
  box-shadow: none !important;
}
.mari-message-avatar > div > button {
  width: calc(2.75rem * var(--roleplay-avatar-scale, 1)) !important;
  height: calc(3.6rem * var(--roleplay-avatar-scale, 1)) !important;
  border-radius: 0 !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  box-shadow: none !important;
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
}
[data-chat-row] img,
[data-chat-row] [data-mari-part="avatar-placeholder"] {
  border-radius: 0 !important;
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
}
[data-chat-row] [data-mari-part="chat-row-art"] {
  -webkit-mask: none;
  mask: none;
}
.ov-recent__avatar,
[data-component="GlobalOmnibar.Panel"] img,
[data-mari-part="mini-avatar"] {
  border-radius: 0 !important;
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
}

/* ===================================================== the reliquary ==== */
.mari-rp-bubble {
  border-radius: 0 !important;
  border: 2px solid transparent !important;
  border-image: var(--ck-frame) 24 fill / 24px stretch !important;
  background: transparent !important;
  box-shadow: none !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  color: var(--ck-ink) !important;
  overflow: visible !important;
}
.mari-rp-bubble > div {
  padding: 0.85rem 1.35rem 0.95rem !important;
}
.mari-rp-bubble--user,
[data-message-role="user"] .mari-rp-bubble {
  border-image: var(--ck-iron) 20 fill / 20px stretch !important;
}
[data-mari-part="message"][data-latest] .mari-rp-bubble {
  border-image: var(--ck-frame-latest) 24 fill / 24px stretch !important;
}
.mari-message-content {
  color: var(--ck-ink);
  max-width: var(--mari-message-measure);
}
.mari-message-content em {
  color: color-mix(in srgb, var(--ck-ink) 82%, var(--ck-gilt));
}
.mari-message-content hr {
  border: 0 !important;
  height: 18px;
  margin: 0.9em auto;
  max-width: 240px;
  background: var(--ck-divider) center / contain no-repeat;
}

/* the speaker's name, struck on a pointed banner plaque */
[data-mari-part="message"] .mari-message-name {
  display: inline-block;
  font-family: "Cinzel", Georgia, serif !important;
  font-weight: 700 !important;
  font-size: 12.5px !important;
  letter-spacing: 0.08em !important;
  text-transform: uppercase;
  color: var(--ck-plaque-text) !important;
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep));
  padding: 3px 16px 2px;
  clip-path: polygon(9px 0, calc(100% - 9px) 0, 100% 50%, calc(100% - 9px) 100%, 9px 100%, 0 50%);
  -webkit-text-stroke: 0 !important;
  line-height: 1.35;
}
[data-mari-part="message"][data-message-role="user"] .mari-message-name {
  background: linear-gradient(180deg, #4a3f3c, #2c2422);
}
:root[data-theme="light"] [data-mari-part="message"][data-message-role="user"] .mari-message-name {
  background: linear-gradient(180deg, #5a4a42, #3a2e28);
}
[data-mari-part="header"] {
  --mari-msg-head-rule: 1px solid color-mix(in srgb, var(--ck-gilt) 40%, transparent);
  align-items: center;
}
[data-mari-part="time"] {
  font-size: 14px !important;
  font-style: italic;
}
[data-mari-part="dialogue"] {
  color: var(--mari-dialogue-color);
}
.ov-rpf__btn {
  color: var(--mari-message-actions);
}

/* conversation: the transcript is a codex page standing in the hall,
   a dark (or vellum) leaf between two gilt rules */
[data-chat-mode="conversation"] .mari-messages-scroll {
  --ck-half: min(32rem, calc(50% - 0.75rem));
  padding-inline: calc(50% - var(--ck-half)) !important;
}
/* the leaf runs the full height of the chat column, down behind the composer, so the composer sits ON
   the page instead of the page stopping short above it */
.mari-chat-area[data-chat-mode="conversation"] {
  --ck-half: min(32rem, calc(50% - 0.75rem));
  background:
    linear-gradient(90deg,
      transparent 0 calc(50% - var(--ck-half) - 2px),
      var(--ck-gilt) calc(50% - var(--ck-half) - 2px) calc(50% - var(--ck-half)),
      var(--ck-leaf) calc(50% - var(--ck-half)) calc(50% + var(--ck-half)),
      var(--ck-gilt) calc(50% + var(--ck-half)) calc(50% + var(--ck-half) + 2px),
      transparent calc(50% + var(--ck-half) + 2px)) !important;
}
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message {
  border-radius: 0 !important;
}
[data-chat-mode="conversation"] .mari-message-content {
  font-family: var(--mari-font-chat) !important;
  color: var(--ck-ink);
}
[data-chat-mode="conversation"] [data-mari-part="avatar"] button {
  border-radius: 0 !important;
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  height: 2.9rem !important;
  width: 2.25rem !important;
}
[data-mari-part="chat-header"] {
  font-family: var(--mari-font-ui);
}
.texting-bubble {
  border-radius: 0 !important;
  border: 2px solid transparent !important;
  border-image: var(--ck-frame) 24 fill / 18px stretch !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--ck-ink) !important;
}

/* game: the narration is a reliquary lectern */
[data-mari-part="message"][data-game-narration] {
  border-radius: 0 !important;
  border: 2px solid transparent !important;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch !important;
  background: transparent !important;
  box-shadow: var(--ck-shadow) !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  border-radius: 0 !important;
  border-color: color-mix(in srgb, var(--ck-gilt) 35%, transparent) !important;
  background: transparent !important;
  font-family: var(--mari-font-chat);
  color: var(--ck-ink);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose > div:first-child {
  font-size: 18px !important;
  line-height: 1.55;
}
[data-mari-part="message"][data-game-narration] > div:first-child > span:first-child {
  border-radius: 0 !important;
  font-family: "Cinzel", Georgia, serif;
  letter-spacing: 0.12em;
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep)) !important;
  color: var(--ck-plaque-text) !important;
  padding: 2px 14px 1px;
  clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 50%, calc(100% - 8px) 100%, 8px 100%, 0 50%);
}
[data-mari-part="game-tools-row"] button,
[data-mari-part="game-tools"] button,
[data-mari-part="game-hud"] {
  border-radius: 0 !important;
}

/* the library gallery: every card is a chapel window */
[data-mari-part="card-art"] {
  border-radius: 0 !important;
  -webkit-mask: url("theme:card-arch.svg") center / 100% 100% no-repeat;
  mask: url("theme:card-arch.svg") center / 100% 100% no-repeat;
}

/* ============================================================ composer == */
/* the altar sill: a heavier reliquary with a lancet for a send button */
.mari-chat-input-box {
  border-radius: 0 !important;
  border: 2px solid transparent !important;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch !important;
  background: transparent !important;
  box-shadow: var(--ck-shadow) !important;
  --tw-ring-shadow: 0 0 #0000 !important;
}
.mari-chat-input-box:focus-within {
  border-image: var(--ck-frame-latest) 24 fill / 24px stretch !important;
}
.mari-chat-input-textarea {
  font-family: var(--mari-font-chat) !important;
  font-size: 17px !important;
  color: var(--ck-ink) !important;
}
.mari-chat-input-textarea::placeholder {
  color: color-mix(in srgb, var(--ck-ink) 60%, transparent) !important;
  font-style: italic;
}
[data-mari-part="composer"] button[aria-label="Send"],
.mari-chat-send-btn {
  background: var(--ck-send) center / 100% 100% no-repeat !important;
  color: var(--ck-plaque-text) !important;
  border-radius: 0 !important;
  /* optical centring: the arch carries its mass low, so the button is shorter than the sill,
     sits with equal clearance from both inner rules, keeps off the corner quatrefoils,
     and the plane rides on the arch's visual centre (a little below the geometric middle) */
  width: 2rem !important;
  height: 2.2rem !important;
  min-height: 0 !important;
  align-self: center !important;
  margin: 0 12px 0 4px !important;
  padding: 7px 0 0 !important;
}
@media (max-width: 640px) {
  [data-mari-part="composer"] button[aria-label="Send"],
  .mari-chat-send-btn { width: 1.7rem !important; height: 1.8rem !important; margin-right: 14px !important; padding-top: 6px !important; }
  [data-mari-part="composer"] button[aria-label="Send"] svg,
  .mari-chat-send-btn svg { width: 14px; height: 14px; }
}
[data-mari-part="composer"] button[aria-label="Send"] svg,
.mari-chat-send-btn svg {
  color: var(--ck-plaque-text) !important;
}
.mari-chat-input-box button img {
  border-radius: 0 !important;
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
}

/* ================================================================ home == */
[data-mari-part="home-widget"] {
  border-radius: 0 !important;
  border: 2px solid transparent !important;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch !important;
  background: transparent !important;
  box-shadow: var(--ck-shadow) !important;
}
[data-mari-part="home-widget-glow"] {
  display: none;
}
[data-mari-part="home-widget-eyebrow"] {
  display: inline-block;
  align-self: flex-start;
  width: max-content;
  font-family: "Cinzel", Georgia, serif !important;
  font-weight: 700 !important;
  letter-spacing: 0.12em !important;
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep));
  color: var(--ck-plaque-text) !important;
  padding: 2px 14px 1px;
  clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 50%, calc(100% - 8px) 100%, 8px 100%, 0 50%);
}
[data-mari-part="home-widget-title"] {
  letter-spacing: 0.03em;
  font-weight: 600 !important;
}
[data-mari-part="home-widget"] [data-mari-part="avatar-placeholder"],
[data-mari-part="home-widget"] img:not([data-mari-part="home-art"]) {
  border-radius: 0 !important;
}
/* the rose window glows through the Recent chats reliquary */
[data-home-widget-id="recent"] [data-mari-part="home-widget"]::after {
  content: "";
  position: absolute;
  right: -3.5rem;
  top: 50%;
  width: 22rem;
  aspect-ratio: 1;
  transform: translateY(-50%);
  background: url("theme:rose-window.webp") center / contain no-repeat;
  opacity: 0.14;
  pointer-events: none;
  z-index: 0;
}
:root[data-theme="light"] [data-home-widget-id="recent"] [data-mari-part="home-widget"]::after {
  opacity: 0.15;
}
@media (max-width: 640px) {
  [data-home-widget-id="recent"] [data-mari-part="home-widget"]::after {
    right: -9rem;
    opacity: 0.1;
  }
}
.ov-home-modes .mari-chrome-control {
  border-radius: 12px 12px 0 0 / 9px 9px 0 0 !important;
  background: var(--popover) !important;
  font-family: "Cinzel", Georgia, serif;
}

/* =================================================== pages & dialogs ==== */
[data-mari-part="page"] {
  font-family: var(--mari-font-ui);
}
[role="dialog"],
.mari-window,
[data-component="GlobalOmnibar.Panel"] {
  border-radius: 0 !important;
  border: 2px solid transparent !important;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch !important;
  background-color: var(--popover) !important;
  box-shadow: 0 18px 50px -20px rgba(0, 0, 0, 0.8) !important;
}


/* =====================================================================
   ROUND 2: the keep's shape language reaches every page
   ===================================================================== */

/* No rounded corners anywhere in the keep: stone is cut, not moulded. The arched doors, lancets and
   plaques above are more specific and keep their own shapes. Spinners stay round. */
#root *:not(.animate-spin, .animate-spin *),
[role="dialog"] *:not(.animate-spin),
[role="menu"],
[role="menu"] *,
[data-react-aria-top-layer] * {
  border-radius: 0 !important;
}

/* One primary: crimson with cream text (5.4:1), in both schemes */
:root {
  --ck-primary: #b82a3a;
  --ck-primary-text: #fff4e6;
  --marinara-app-accent-solid: #b82a3a;
}
.ov-btn--primary,
.mari-chrome-control--primary,
.mari-editor-action--primary,
button.bg-\[var\(--primary\)\] {
  background: linear-gradient(180deg, var(--ck-primary), #8a1a28) !important;
  color: var(--ck-primary-text) !important;
  border: 1px solid var(--ck-gilt) !important;
}
.ov-btn--primary svg,
.mari-chrome-control--primary svg {
  color: var(--ck-primary-text) !important;
}

/* Buttons are arched doors; icon buttons and fields are square stone */
.ov-btn,
.mari-editor-action,
.mari-editor-tab,
.ov-home-hero-buttons button {
  border-radius: 12px 12px 0 0 / 9px 9px 0 0 !important;
  font-family: var(--mari-font-ui);
}
.ov-btn--icon,
.ov-search,
.ov-select,
.ov-search input {
  border-radius: 0 !important;
}
.ov-btn--primary,
.ov-home-hero-buttons button,
.ov-btn {
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.ov-btn--icon {
  font-family: inherit;
}
.ov-search {
  background: var(--ck-field) !important;
  border: 1px solid var(--ov-line) !important;
}

/* Segmented choices: a row of stone plates, the chosen one a crimson plate with a gilt sill */
.ov-seg {
  border-radius: 0 !important;
  border-color: var(--ov-line) !important;
  background: var(--ck-field);
}
.ov-seg button {
  border-radius: 0 !important;
}
.ov-seg button.is-on,
.ov-seg button[aria-checked="true"] {
  background: linear-gradient(180deg, var(--ck-primary), #8a1a28) !important;
  color: var(--ck-primary-text) !important;
  box-shadow: inset 0 -2px 0 var(--ck-gilt);
}

/* One switch everywhere: a square stone slot, crimson when on, a gilt square knob */
:is([data-settings-switch-track], .ov-switch, .ovm-csq__track) {
  border-radius: 0 !important;
  background: var(--ck-slot) !important;
  box-shadow: inset 0 0 0 1px var(--ov-line) !important;
}
:is([data-settings-switch-thumb], .ov-switch span, .ovm-csq__thumb) {
  border-radius: 0 !important;
  background: var(--ck-knob-off) !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4) !important;
}
:is([data-settings-switch-track][data-checked], .ov-switch.is-on, .ov-switch[aria-checked="true"], .ovm-csq__switch.is-on .ovm-csq__track) {
  background: linear-gradient(180deg, var(--ck-primary), #8a1a28) !important;
  box-shadow: inset 0 0 0 1px var(--ck-gilt) !important;
}
:is([data-settings-switch-track][data-checked], .ov-switch.is-on, .ov-switch[aria-checked="true"], .ovm-csq__switch.is-on .ovm-csq__track)
  :is([data-settings-switch-thumb], span, .ovm-csq__thumb) {
  background: linear-gradient(180deg, #f0d48a, #c9a24a) !important;
}
input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--ck-primary);
}

/* Tables: a cut-corner ledger with a gilt head rule and mortar lines between rows */
.ov-table-wrap {
  border: 2px solid transparent !important;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch !important;
  background: transparent !important;
  padding: 4px 6px;
}
.ov-table thead th {
  font-family: "Cinzel", Georgia, serif;
  letter-spacing: 0.08em;
  border-bottom: 1px solid var(--ck-gilt) !important;
  color: var(--mari-accent-text) !important;
}
.ov-table tbody tr td {
  border-bottom: 1px solid var(--ov-line) !important;
  font-size: 15px;
}
.ov-thumb {
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
}

/* Library cards: count badges square, the menu tucked below the arch shoulder, the new card a
   dashed chapel-window outline */
[data-mari-part="card-art"] ~ * button,
.ov-card__more {
  top: 26% !important;
}
.ov-card--new,
[class*="ov-card"][class*="--new"] {
  border: 0 !important;
  background: url("theme:card-arch-dash.svg") center / 100% 100% no-repeat !important;
}

/* Dialogs and sheets are reliquaries on a crimson-black scrim, titled on a plaque */
.mari-modal-panel,
.marinara-chat-popover,
.mari-drawer-sheet,
[data-component="GlobalOmnibar.Panel"] {
  border-radius: 0 !important;
  border: 2px solid transparent !important;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch !important;
  background: var(--popover) !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  box-shadow: 0 18px 50px -20px rgba(0, 0, 0, 0.8) !important;
}
[role="dialog"].mari-modal,
[role="dialog"][data-component="Modal"] {
  border: 0 !important;
  border-image: none !important;
  background: transparent !important;
  box-shadow: none !important;
}
.mari-modal-backdrop {
  background: var(--mari-scrim) !important;
}
.marinara-chat-popover__title,
.mari-modal-panel h2 {
  font-family: "Cinzel", Georgia, serif !important;
  font-weight: 700 !important;
  font-size: 14px !important;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ck-plaque-text) !important;
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep));
  padding: 3px 18px 2px !important;
  clip-path: polygon(9px 0, calc(100% - 9px) 0, 100% 50%, calc(100% - 9px) 100%, 9px 100%, 0 50%);
  width: max-content;
  max-width: 100%;
}

/* Menus and toasts: small iron-bound panels with rivets */
[role="menu"],
[data-sonner-toast],
.mari-toast {
  border: 2px solid transparent !important;
  border-image: var(--ck-iron) 20 fill / 20px stretch !important;
  background: var(--popover) !important;
  box-shadow: 0 10px 30px -14px rgba(0, 0, 0, 0.8) !important;
  font-family: var(--mari-font-ui);
}
[data-sonner-toast] {
  font-size: 15px !important;
}

/* Chat settings sheet (phones and tablets) and Settings rows: stone courses, not grey cards */
.ovm-cs-row__btn,
.ovm-csq__switch,
.ovm-csq__all,
.ov-cs .mari-drawer__body button:not([role="switch"]):not([class*="ov-"]) {
  border-radius: 0 !important;
  background: var(--ck-course) !important;
  box-shadow: inset 0 0 0 1px var(--ov-line) !important;
}
.ovm-cs-row__title,
.ovm-csq__switch > span:last-child {
  font-size: 15px !important;
}
.ov-cs__title,
.ovm-cs__title,
[data-ovm-cs-view] h2 {
  letter-spacing: 0.02em !important;
}

/* The roleplay name line outside the frame (phones, iPad portrait): only the plaque is filled */
.mari-message-body > div.flex.items-baseline {
  background: transparent !important;
  box-shadow: none !important;
}

/* Home: every shortcut is an arched door; phones keep them on one row */
.ov-home-hero-buttons button {
  background: var(--popover) !important;
  border: 1px solid var(--ov-line) !important;
  border-bottom-color: var(--ck-gilt) !important;
}
@media (max-width: 640px) {
  /* two compact rows (stock is two 43px rows): the three doors share row one, Professor/Widgets row two */
  .ov-home-hero-buttons {
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 6px !important;
  }
  .ov-home-modes {
    display: flex !important;
    flex-wrap: nowrap !important;
    gap: 6px !important;
    width: 100% !important;
  }
  .ov-home-modes button { flex: 1 1 auto !important; min-width: 0 !important; padding-inline: 6px !important; }
  .ov-home-hero-actions {
    display: flex !important;
    gap: 6px !important;
    justify-content: flex-start !important;
  }
  .ov-home-hero-buttons button {
    padding-inline: 8px !important;
    height: 2.15rem !important;
    min-height: 0 !important;
    gap: 6px !important;
    font-size: 14px !important;
  }
  .ov-home-hero-buttons button > span:first-child:has(> svg) {
    width: auto !important;
    height: auto !important;
    border: 0 !important;
    background: none !important;
    box-shadow: none !important;
  }
  .ov-home-hero-buttons button span {
    font-size: 14px !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

/* Conversation header: the speaker on an iron plaque */
[data-mari-part="chat-header"] button {
  border: 2px solid transparent !important;
  border-image: var(--ck-iron) 20 fill / 16px stretch !important;
  background: transparent !important;
}

/* Portraits everywhere are lancet windows: editors, Ctrl+K, the Library sidebar */
.ov-ed__avatar,
.ov-ed-avatar,
[data-component="OverhaulEditorRail"] img,
[data-component="OverhaulEditorRail"] [data-mari-part="avatar-placeholder"],
[data-component="GlobalOmnibar.Panel"] [data-mari-part="avatar-placeholder"],
.ov-gpane__av {
  -webkit-mask: url("theme:card-arch.svg") center / 100% 100% no-repeat;
  mask: url("theme:card-arch.svg") center / 100% 100% no-repeat;
}
.ov-gpane__av {
  -webkit-mask-image: url("theme:lancet-mask.svg");
  mask-image: url("theme:lancet-mask.svg");
}

/* Tag chips are little banner plaques */
.ov-tag,
.ov-chip,
.ov-ed__tag {
  clip-path: polygon(6px 0, calc(100% - 6px) 0, 100% 50%, calc(100% - 6px) 100%, 6px 100%, 0 50%);
  padding-inline: 12px !important;
  border: 0 !important;
  background: var(--ck-course) !important;
}

/* Game: the party pane is the most ornate panel in the keep */
.ov-gpane {
  border-left: 1px solid var(--ck-gilt) !important;
  background:
    linear-gradient(180deg, var(--ck-pane-top), var(--ck-pane-bottom)) !important;
}
.ov-gpane__head {
  border-bottom: 1px solid var(--ck-gilt) !important;
  font-family: "Cinzel", Georgia, serif;
}
.ov-gpane__tabs button {
  border-radius: 12px 12px 0 0 / 9px 9px 0 0 !important;
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
}
.ov-gpane__tabs button.is-on {
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep)) !important;
  color: var(--ck-plaque-text) !important;
}
.ov-gpane__tabs button.is-on svg {
  color: var(--ck-plaque-text) !important;
}
.ov-gpane__body {
  margin: 8px;
  border: 2px solid transparent;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch;
}
.ov-gpane__table th {
  font-family: "Cinzel", Georgia, serif;
  letter-spacing: 0.1em;
  color: var(--mari-accent-text) !important;
  border-bottom: 1px solid var(--ck-gilt) !important;
}
.ov-gpane__table td {
  border-bottom: 1px solid var(--ov-line) !important;
  font-size: 15px;
}
[data-mari-part="game-hud"] [data-tour="game-map"] {
  border: 2px solid transparent !important;
  border-image: var(--ck-iron) 20 fill / 18px stretch !important;
  background: transparent !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
[data-mari-part="message"][data-game-narration] .anim-text-flicker {
  color: var(--ck-ember) !important;
}

/* Library sidebar: the open page is a lit niche like the open chat */
.ov-libnav__item.is-on,
.ov-libnav__item[aria-current="page"] {
  box-shadow: inset 3px 0 0 var(--ck-gilt) !important;
}

/* Settings: section labels on a gilt rule, descriptions at reading size */
[data-component="OverhaulSettingsPage"] p,
[data-mari-part="page"] .text-\[0\.6875rem\],
[data-mari-part="page"] .text-\[0\.75rem\],
[data-mari-part="page"] .text-\[0\.625rem\] {
  font-size: 14px !important;
}

/* ============================================================== phones == */
@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
  }
}

/* body/row text floor off the chat screens: nothing in the keep is set below 14px */
.mari-home-widget-shortcut__description,
.ov-recent__mode,
[data-mari-part="home-widget-eyebrow"],
.ov-home-hero-actions .ov-btn,
.ov-recent__all-label,
.mari-chrome-control--compact {
  font-size: max(14px, 1em) !important;
}
.mari-message-name { font-size: max(14px, 1em) !important; }
.ov-sideswitch__btn, .ov-sideswitch__btn span { font-size: 14px !important; }
.ov-card__tokens { font-size: 14px !important; }
/* chat-list rows on every device: each portrait is a lancet */
[data-chat-row] img {
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  border-radius: 0 !important;
}
[data-chat-row] span:has(> img) { --tw-ring-shadow: 0 0 #0000 !important; box-shadow: none !important; border-radius: 0 !important; overflow: visible !important; }
@media (max-width: 640px) {
  /* the three doors in one row: plain small capitals in the book face, no icons, so nothing is cut */
  .ov-home-modes button,
  .ov-home-modes button span {
    font-family: var(--mari-font-ui) !important;
    font-weight: 600 !important;
    letter-spacing: 0.02em !important;
    font-size: 15px !important;
    text-transform: none !important;
  }
  .ov-home-hero-buttons > .ov-home-modes { width: 100% !important; align-self: stretch !important; flex: none !important; }
  .ov-home-hero-actions .ov-btn {
    font-family: var(--mari-font-ui) !important;
    font-weight: 600 !important;
    letter-spacing: 0.02em !important;
    font-size: 15px !important;
    text-transform: none !important;
    height: 2.15rem !important;
    min-height: 0 !important;
  }
}

/* =====================================================================
   ROUND 3: the arched doorways come back. The square-everything rule above has an id in it, so the
   doorways restate their arches with #root: top-bar tabs, the Chats | Library pair, + New, the
   Convo / Roleplay / Game filter and Home's mode row. Everything else stays square.
   ===================================================================== */
#root [data-mari-part="top-bar"] .ov-tab,
#root [data-mari-part="top-bar"] .ov-text-btn {
  border-radius: 14px 14px 0 0 / 10px 10px 0 0 !important;
}
#root .ov-sideswitch__btn {
  border-radius: 50% 50% 0 0 / 16px 16px 0 0 !important;
}
#root .ov-new-pill,
#root .ov-home-hero-buttons button,
#root .ov-home-hero-buttons .ov-btn {
  border-radius: 12px 12px 0 0 / 9px 9px 0 0 !important;
}
#root .mari-chrome-segmented__button {
  border-radius: 12px 12px 0 0 / 9px 9px 0 0 !important;
  border: 1px solid transparent !important;
  border-bottom: 0 !important;
}
#root .mari-chrome-segmented__button--selected {
  border-color: var(--ck-gilt) !important;
  box-shadow: none !important;
}
#root .mari-chrome-segmented {
  border-bottom: 1px solid var(--ck-gilt) !important;
  gap: 4px;
}
@media (max-width: 640px) {
  #root .ov-home-hero-buttons button,
  #root .ov-home-hero-buttons .ov-btn {
    border-radius: 10px 10px 0 0 / 7px 7px 0 0 !important;
  }
  .ov-home-modes button { gap: 4px !important; }
  .ov-home-modes button svg { width: 15px; height: 15px; }
}

/* game side pane: the five tabs always all show. Book face instead of Cinzel capitals, tight padding,
   and they wrap to a second course rather than ever being cut */
.ov-gpane__tabs {
  flex-wrap: wrap !important;
  overflow: visible !important;
  row-gap: 4px !important;
  column-gap: 2px !important;
  height: auto !important;
}
.ov-gpane__tabs button {
  font-family: var(--mari-font-ui) !important;
  font-size: 14px !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
  padding-inline: 5px !important;
  gap: 3px !important;
  flex: none !important;
  white-space: nowrap;
}

/* Toggles (round 3): a square gilt-framed slot in both states. Off: the slot is the page colour and the knob
   is an empty gilt-outlined square at the left. On: crimson slot, solid gilt knob at the far right.
   The state reads from the knob's position and fill, not only from colour. */
#root :is([data-settings-switch-track], .ov-switch, .ovm-csq__track) {
  background: var(--background) !important;
  box-shadow: inset 0 0 0 1px var(--ck-gilt) !important;
  border: 0 !important;
}
#root :is([data-settings-switch-thumb], .ov-switch span, .ovm-csq__thumb) {
  background: var(--background) !important;
  box-shadow: inset 0 0 0 1.5px var(--ck-gilt) !important;
  --tw-ring-shadow: 0 0 #0000 !important;
}
#root :is([data-settings-switch-track][data-checked], .ov-switch.is-on, .ov-switch[aria-checked="true"], .ovm-csq__switch.is-on .ovm-csq__track) {
  background: linear-gradient(180deg, var(--ck-primary), #8a1a28) !important;
  box-shadow: inset 0 0 0 1px var(--ck-gilt) !important;
}
#root :is([data-settings-switch-track][data-checked], .ov-switch.is-on, .ov-switch[aria-checked="true"], .ovm-csq__switch.is-on .ovm-csq__track)
  :is([data-settings-switch-thumb], span, .ovm-csq__thumb) {
  background: linear-gradient(180deg, #f0d48a, #c9a24a) !important;
  box-shadow: 0 0 0 1px #6e5212 !important;
}

/* RP timestamps can sit on bare window art: a soft halo of the page colour keeps them >= 4.5:1 */
:root[data-theme="light"] [data-mari-part="time"] {
  color: #4a3a2e !important;
  text-shadow: 0 0 3px #fbf6ec, 0 0 6px #fbf6ec, 0 0 10px rgba(251, 246, 236, 0.8);
}
:root[data-theme="dark"] [data-mari-part="time"] {
  color: #d3c0a4 !important;
  text-shadow: 0 0 3px #12080b, 0 0 6px #12080b, 0 0 10px rgba(18, 8, 11, 0.85);
}

/* ROUND 3 small fixes */
/* day Settings lists are parchment like the chat-settings sheet rows, not neutral grey */
:root[data-theme="light"] .ovm-settings__rows {
  background: #f7f0e2 !important;
  border: 1px solid #d9c9ac !important;
}
:root[data-theme="light"] .ovm-settings__rows > * + * {
  border-top-color: #d9c9ac !important;
}
/* editor primary actions (+ New entry) get the same inner padding as their neighbours */
.mari-editor-action {
  padding-inline: 10px !important;
  gap: 6px !important;
}
/* a lorebook with no picture: a parchment/stone niche with a gilt book, not a blue square */
.ov-povw__thumb.mari-panel-gradient-surface,
.mari-panel-gradient--lorebooks.ov-povw__thumb {
  background: var(--ck-slot) !important;
  border: 1px solid var(--ck-gilt) !important;
  color: var(--ck-gilt) !important;
  -webkit-mask: none;
}
.ov-povw__thumb.mari-panel-gradient-surface svg { color: var(--ck-gilt) !important; }
/* toast close: a small plaque inside the top-right corner, clear of the rivets */
[data-sonner-toast] [data-close-button] {
  left: auto !important;
  right: 14px !important;
  top: 12px !important;
  transform: none !important;
  width: 22px !important;
  height: 22px !important;
  background: transparent !important;
  border: 1px solid color-mix(in srgb, var(--ck-gilt) 70%, transparent) !important;
  color: var(--ck-gilt) !important;
}
[data-sonner-toast] { padding-right: 44px !important; }
/* conversation header plate: room to breathe */
#root [data-mari-part="chat-header"] button[data-chat-help="identity"] {
  height: auto !important;
  min-height: 2.6rem !important;
  padding: 8px 14px 8px 10px !important;
  gap: 10px !important;
}
#root [data-mari-part="chat-header"] button[data-chat-help="identity"] * {
  font-size: max(14px, 1em) !important;
  line-height: 1.25 !important;
}
/* Connections: the Defaults table wears the same reliquary frame as the accounts table */
.ov-conn-defaults {
  border: 2px solid transparent !important;
  border-image: var(--ck-frame-panel) 24 fill / 24px stretch !important;
  background: transparent !important;
  padding: 10px 12px !important;
}
/* phone chat-settings sheet: the title plaque never truncates; Edit gives up its word, keeps its pencil */
@media (max-width: 640px) {
  .marinara-chat-popover__title.mari-window__title {
    flex-shrink: 0 !important;
    overflow: visible !important;
    text-overflow: clip !important;
    max-width: none !important;
    letter-spacing: 0.03em !important;
  }
  .ov-cs__head .ov-edbtn {
    font-size: 0 !important;
    padding: 4px 8px !important;
    gap: 0 !important;
  }
  .ov-cs__head .ov-edbtn svg { width: 16px; height: 16px; }
}

/* Ctrl+K results: portraits are lancets too */
.result-type-icon img,
.result-type-icon > span,
[role="dialog"] .result-type-icon :is(span, div):has(> img) {
  border-radius: 0 !important;
  -webkit-mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
  mask: url("theme:lancet-mask.svg") center / 100% 100% no-repeat;
}

/* =====================================================================
   ROUND 4
   ===================================================================== */
/* New Conversation wizard: its plain div switch wears the keep's toggle */
div.h-5.w-9.rounded-full.p-0\.5 {
  border-radius: 0 !important;
  background: var(--background) !important;
  box-shadow: inset 0 0 0 1px var(--ck-gilt) !important;
}
div.h-5.w-9.rounded-full.p-0\.5 > * {
  border-radius: 0 !important;
  background: var(--background) !important;
  box-shadow: inset 0 0 0 1.5px var(--ck-gilt) !important;
}
div.h-5.w-9.rounded-full.p-0\.5.bg-\[var\(--primary\)\] {
  background: linear-gradient(180deg, var(--ck-primary), #8a1a28) !important;
}
div.h-5.w-9.rounded-full.p-0\.5.bg-\[var\(--primary\)\] > * {
  background: linear-gradient(180deg, #f0d48a, #c9a24a) !important;
  box-shadow: 0 0 0 1px #6e5212 !important;
}

/* A chat's own picture is hung in the keep: a thin gilt inner rule and a soft vignette over the picture
   (never a window mask). Game stage: the stage's picture layer; roleplay: the app's vignette layer, only
   while the backdrop shows the chat's own picture. */
:root[data-chat-open-mode="game"] div.bg-cover[style*="background-image"] {
  outline: 1px solid color-mix(in srgb, var(--ck-gilt) 85%, transparent);
  outline-offset: -8px;
  box-shadow: inset 0 0 0 7px rgba(10, 5, 7, 0.35), inset 0 0 160px 20px rgba(10, 5, 7, 0.55) !important;
}
:has(> img[data-mari-part="backdrop"][src]:not([data-default-background])) > .rpg-vignette {
  outline: 1px solid color-mix(in srgb, var(--ck-gilt) 85%, transparent);
  outline-offset: -8px;
  box-shadow: inset 0 0 0 7px rgba(10, 5, 7, 0.3), inset 0 0 160px 20px rgba(10, 5, 7, 0.5) !important;
}

/* phone RP timestamps: heavier and a wider halo over bright glass */
@media (max-width: 640px) {
  [data-mari-part="time"] { font-weight: 600 !important; }
  :root[data-theme="light"] [data-mari-part="time"] {
    text-shadow: 0 0 3px #fbf6ec, 0 0 6px #fbf6ec, 0 0 12px #fbf6ec, 0 0 18px rgba(251, 246, 236, 0.9);
  }
  :root[data-theme="dark"] [data-mari-part="time"] {
    text-shadow: 0 0 3px #12080b, 0 0 6px #12080b, 0 0 12px #12080b, 0 0 18px rgba(18, 8, 11, 0.9);
  }
}

/* Home's mode row: all five doors arched, phone and tablet included */
#root .ov-home-hero-actions > button,
#root .ov-home-hero-actions > .ov-btn,
#root .ov-home-modes > button {
  border-radius: 12px 12px 0 0 / 9px 9px 0 0 !important;
}
@media (max-width: 640px) {
  #root .ov-home-hero-actions > button,
  #root .ov-home-hero-actions > .ov-btn,
  #root .ov-home-modes > button {
    border-radius: 10px 10px 0 0 / 7px 7px 0 0 !important;
  }
}

/* day sidebar: the open chat gets the gilt left edge like the night niche */
:root[data-theme="light"] [data-chat-row][data-selected="true"],
:root[data-theme="light"] .ov-libnav__item.is-on {
  box-shadow: inset 3px 0 0 var(--ck-gilt) !important;
  background: linear-gradient(90deg, rgba(201, 162, 74, 0.22), rgba(201, 162, 74, 0.04) 85%) var(--ck-row-solid) !important;
}

/* Settings sub-sections and similar chips: small arched doors with an iron sill */
#root .ov-chip {
  clip-path: none !important;
  border-radius: 10px 10px 0 0 / 7px 7px 0 0 !important;
  border: 1px solid var(--ov-line) !important;
  border-bottom: 2px solid color-mix(in srgb, var(--ck-gilt) 70%, transparent) !important;
  background: color-mix(in srgb, var(--popover) 80%, transparent) !important;
}
#root .ov-chip.is-on,
#root .ov-chip[aria-pressed="true"],
#root .ov-chip[aria-selected="true"] {
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep)) !important;
  color: var(--ck-plaque-text) !important;
  border-color: var(--ck-gilt) !important;
}
/* Ctrl+K section labels on a small crimson plaque */
h3[id^="omnibar-group-"] {
  font-family: "Cinzel", Georgia, serif !important;
  color: var(--ck-plaque-text) !important;
  background: linear-gradient(180deg, var(--ck-crimson), var(--ck-crimson-deep));
  padding: 1px 12px 1px 10px;
  clip-path: polygon(0 0, calc(100% - 7px) 0, 100% 50%, calc(100% - 7px) 100%, 0 100%);
  letter-spacing: 0.1em !important;
}
h3[id^="omnibar-group-"] + * { color: var(--muted-foreground); }
#root .ov-chip { font-size: 14px !important; }

/* =====================================================================
   ROUND 5
   ===================================================================== */
/* phone: the collapsed one-line composer (shown while scrolled up) is the same reliquary, with the
   expanded composer's inset and no square blur plate behind its chamfered corners */
.mari-chat-input-box,
button.mari-chat-input-box[aria-label="Show message input"] {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  box-shadow: none !important;
}
#root button.mari-chat-input-box[aria-label="Show message input"] {
  background: transparent !important;
  padding-left: 22px !important;
  padding-right: 18px !important;
  min-height: 2.9rem !important;
  font-family: var(--mari-font-chat) !important;
  font-style: italic;
  color: color-mix(in srgb, var(--ck-ink) 62%, transparent) !important;
}
/* wizard switch: the frame is the gilt rule itself (no 16% crimson border from the app) */
div.h-5.w-9.rounded-full.p-0\.5 {
  border: 1px solid var(--ck-gilt) !important;
  box-shadow: none !important;
  outline: 0 !important;
}
/* a chat's own picture becomes a place in the keep: a carved stone lintel with a gilt corbel-arch beading
   runs along the top of the game stage / own-picture roleplay backdrop (an overlay: no layout height) */
:root[data-chat-open-mode="game"] div:has(> div.bg-cover[style*="background-image"])::after,
:has(> img[data-mari-part="backdrop"][src]:not([data-default-background])) > .rpg-vignette::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 18px;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 100%, transparent 5.5px, var(--ck-gilt) 6px 7px, transparent 7.5px) 0 2px / 16px 9px repeat-x,
    linear-gradient(180deg, transparent 0 15px, var(--ck-gilt) 15px 16px, transparent 16px),
    linear-gradient(180deg, var(--ck-lintel-a), var(--ck-lintel-b) 15px, transparent 15px);
  box-shadow: 0 6px 10px -6px rgba(0, 0, 0, 0.6);
  z-index: 1;
}
:root[data-theme="dark"] { --ck-lintel-a: #2a1a1f; --ck-lintel-b: #160c10; }
:root[data-theme="light"] { --ck-lintel-a: #e9dcc3; --ck-lintel-b: #d6c5a4; }
:root[data-chat-open-mode="game"] div:has(> div.bg-cover[style*="background-image"]) { isolation: isolate; }
/* Library list rows: the placeholder thumbnail is a small gilt lancet, not a dark blob */
.ov-table .ov-thumb {
  width: 24px !important;
  height: 32px !important;
  -webkit-mask: none !important;
  mask: none !important;
  background: var(--ck-lancet-frame) center / 100% 100% no-repeat !important;
  border-radius: 0 !important;
  flex: none;
}
/* Library page titles stand on a carved lintel: gilt corbel-arch beading under the blackletter */
[data-mari-part="page-title"] {
  padding-bottom: 12px !important;
  background:
    radial-gradient(circle at 50% 100%, transparent 4.5px, var(--ck-gilt) 5px 6px, transparent 6.5px) 0 calc(100% - 1px) / 13px 7px repeat-x,
    linear-gradient(var(--ck-gilt), var(--ck-gilt)) 0 100% / 100% 1px no-repeat !important;
}
/* the speaker chip's sticky strip is a band of the leaf, so lines scroll under a plaque rather than show
   through around it */
[data-chat-mode="conversation"] .mari-messages-scroll > .sticky.top-0 {
  background: linear-gradient(180deg,
    var(--ck-leaf-solid) 0 calc(100% - 12px),
    transparent 100%) !important;
  padding-bottom: 14px !important;
}

/* =====================================================================
   FINAL POLISH
   ===================================================================== */
/* stage widgets clear the lintel (the map card on desktop, the Map / Party bubbles on phones): they are
   overlays, so moving them down adds no height */
:root[data-chat-open-mode="game"] [data-tour="game-map"],
:root[data-chat-open-mode="game"] [data-tour="game-party"] {
  margin-top: 20px !important;
}
/* night blossom: a moonlit pale-rose set (crimson heart) at a larger size, so a few always read on the night glass */
:root[data-theme="dark"] {
  --mari-weather-petal-image: url("theme:wx-petal-n1.png") url("theme:wx-petal-n2.png") url("theme:wx-petal-n3.png");
  --mari-weather-petal-size: 1.8;
}

/* Readability: tables and dense lists sit on solid ledger stone, never see-through to the hall */
[data-chat-row],
.ov-libnav__group {
  background-color: var(--ck-row-solid);
}
